function shell(content) {
  const isActive = href => href === '/the-house' ? ['/', '/the-house'].includes(location.pathname) : location.pathname === href || location.pathname.startsWith(`${href}/`);
  return `<header><a class="brand" href="/the-house"><img src="/images/c83a1e4df304aeb0.jpg" alt="Country Beach Escape logo"><span>Country Beach Escape</span></a><button class="menu" aria-label="Toggle menu">☰</button><nav>${nav.map(([href,label])=>`<a href="${href}"${isActive(href) ? ' class="nav-active" aria-current="page"' : ''}>${label}</a>`).join('')}</nav></header><main>${content}</main><footer>Gated Community Country Beach Escape</footer>`;
}
const button = (label, href=booking) => `<a class="button" href="${href}"${href.startsWith('http') ? ' target="_blank" rel="noreferrer"' : ''}>${label}</a>`;
function home(){return `
  <section class="home-intro"><h1>Gated Community Country Beach Escape</h1><p class="tagline">A much loved &amp; enjoyed 4 Bed home from home in the beauty of Ballymoney, Gorey, Co. Wexford</p><p class="sleeps">4 Bedroom Holiday House in Wexford Sleeping 8</p><p class="description">Country Beach Escape is a luxury four-bedroom self-catering holiday home near Ballymoney Beach, Gorey, County Wexford. Sleeping up to eight guests with a private hot tub, large garden and spacious family accommodation, it is ideal for beach holidays, golf breaks and relaxing getaways on Ireland's Sunny South East.</p></section>
  <section class="video-grid"><article><iframe src="https://www.youtube.com/embed/h1V904Dt3JM" title="Chalk & Cheese Travels" allowfullscreen></iframe><h2>Thanks to Chalk &amp; Cheese Travels<br>for featuring us!</h2><p><a href="https://www.instagram.com/chalkandcheesetravels/" target="_blank">@chalkandcheesetravels</a></p></article><article><iframe src="https://www.youtube.com/embed/TSq83g_t_f8" title="Country Beach Escape video" allowfullscreen></iframe><h2>See our new Cheesy Video to get a feel of your stay at Country Beach Escape!</h2><p>Pack your bags, hit the coast for the place we love the most!</p></article></section>
  <section class="booking-links">${button('Airbnb Page',airbnb)} ${button('Book Direct – Best Price Guarantee')}</section>
  <section class="reservations"><h2>Reservations</h2><p>See <a href="${airbnb}">Airbnb Page</a> for the most up to date availability and rates.</p><p>For <strong>SIGNIFICANTLY LOWER nightly rates</strong>, <a href="${booking}">Enquire Here or Book Direct.</a></p><p>WhatsApp or Phone Julianne: <a href="tel:+353868215176">0868215176</a></p></section>
  <section class="quotes"><blockquote>“‘Ghostis’ is the Indo–European root and it describes neither the host nor the guest but the relationship between the two. Hospitality is the space of possibility that opens up between guest and host when both parties willingly engage in this precarious mutual trust.”<cite>Visser, 1991, p.91</cite></blockquote><blockquote>“Fab communication, beautiful house, everything you could ever need.”<cite>Happy Guest</cite></blockquote><blockquote>“Stayed here just last night. And we absolutely loved it. It is a perfect combination of home away from home, yet the luxury of a hotel stay.”<cite>Happy Guest</cite></blockquote></section>`}
function faq(){const faqs=[
 ['Where are you located?','Ballymoney, Gorey, Co Wexford. We are in a quiet residential gated community called The Meadows, just opposite the popular Orphan Girl Pub (four minutes\' walk). Access is through a locked gate; the code is provided at check-in. We are right beside the popular Tara Meadows Holiday Park.'],
 ['How far is Gorey town?','Gorey is approximately a 10-minute drive from Country Beach Escape. Gorey is your nearest major town and has supermarkets, cafés, restaurants, pubs, boutiques, a cinema and everyday services. The town is also a useful starting point for exploring North Wexford.'],
 ['How far is Wexford Town?','Wexford Town is about a 45-minute drive away. You have direct access to the M11 five minutes from the house, making it easy to explore North and South Wexford.'],
 ['How far are you from Rosslare Europort? We\'re thinking of arriving by ferry.','Rosslare Europort is about an hour\'s drive away. Take Exit 23 for the most direct access to the house; Country Beach Escape is about five minutes from the exit. <a href="https://www.rosslareeuroport.ie/en-ie" target="_blank" rel="noreferrer">Rosslare Europort — official website</a>.'],
 ['Can we visit Dublin during our stay?','Yes. Dublin is close enough for a day trip, although I recommend treating it as a full day rather than trying to squeeze in a few hours. The house is approximately an hour from Dublin in normal conditions, although traffic can significantly increase journey times. For guests who want to explore Dublin without driving into the city centre, travelling by car to a suitable park-and-ride or public transport connection can be worth considering. There is access to Dublin from Gorey Train Station, which has free parking, and a Wexford Bus that leaves from Gorey Main Street.'],
 ['How do we get to Country Beach Escape from Dublin Airport?','Country Beach Escape is easy to reach from Dublin Airport, and you do not need to travel into Dublin city centre first.<br><br><strong>By car</strong><br>Hiring a car at Dublin Airport is the easiest option for most guests. From Dublin Airport, follow the M50 south and then the M11 towards Wexford and Gorey. From Gorey, Country Beach Escape is a short drive towards Ballymoney. Having a car is also useful during your stay for exploring the beaches, restaurants and attractions around North Wexford.<br><br><strong>Tip:</strong> The M50 uses barrier-free tolling, so visitors using a rental car should check with their car-hire company how the M50 toll is handled.<br><br><strong>Direct bus to Gorey</strong><br>If you do not want to hire a car, there are direct coach services from Dublin Airport to Gorey with <a href="https://www.wexfordbus.com/" target="_blank" rel="noreferrer">Wexford Bus</a>. The journey generally takes approximately 1½–2 hours, depending on the service and traffic. From Gorey, simply take a taxi for the final short journey to Country Beach Escape. This is usually the simplest public-transport option because there is no need to travel into Dublin city centre or change onto a train.<br><br><strong>Private airport transfer</strong><br>For families or groups travelling with luggage, a pre-booked taxi or private airport transfer can take you directly from Dublin Airport to the door of Country Beach Escape. This is the easiest door-to-door option and can be particularly convenient after a long flight.<br><br><strong>By train</strong><br>Gorey has a railway station with services from Dublin, but Dublin Airport itself does not have a train station. You would first need to travel from the airport into Dublin and then take a train towards Gorey. For that reason, we normally recommend the direct airport-to-Gorey coach with <a href="https://www.wexfordbus.com/" target="_blank" rel="noreferrer">Wexford Bus</a> instead.<br><br><strong>Which option do we recommend?</strong><br><strong>Hiring a car:</strong> Best if you plan to explore North Wexford during your holiday.<br><strong>Direct coach + taxi (or local bus link):</strong> Best value if you do not want to drive. You can also use the <a href="https://goreybuslinks.ie/" target="_blank" rel="noreferrer">Gorey Bus service</a>, which stops at The Orphan Girl and Hughes Londis in Ballymoney — our closest stop.<br><strong>Private airport transfer:</strong> Easiest option for families and groups with lots of luggage.<br><br>If you are unsure about the best way to reach us, <a href="/contact-us">contact us before your stay</a> and we will be happy to help you plan your journey to Country Beach Escape.'],
 ['What can we do with children near Gorey?','North Wexford is particularly good for family holidays. One of the best nearby options, five minutes from the house, is Kia Ora Mini Farm near Gorey. Children can meet and feed animals, use the mini diggers, ride the fire engine, explore the maze and enjoy go-karts and other activities. The farm is fully wheelchair and buggy accessible and has free parking. <a href="https://kiaoraminifarm.ie/?utm_source=chatgpt.com" target="_blank" rel="noreferrer">Kia Ora Mini Farm — official website</a>.'],
 ['What is there to do for teenagers?','Teenagers have plenty of options around Gorey and Courtown. Depending on the weather, possibilities include:<br><br><strong>Active Tribe, Courtown</strong><br>Swimming, water slide, zipline, high climbing course, archery and more.<br><br><strong>Pirates Cove, Courtown</strong><br>Bowling, adventure golf, arcade games and water activities.<br><br>Other great options include beach trips, swimming, cinema visits, exploring Gorey town, coastal walks, and watersports and outdoor activities in suitable weather.'],
 ['What can we do on a rainy day?','Don\'t worry if you get a wet day — I have set up the house specifically with rainy days in mind. There are lots of games and crafts in the white cupboard in the kitchen next to the fridge. Magnatiles are in the green cabinet on the right in the lounge, along with game consoles; wool and material crafts are in the green cabinet on the left. There are card games in the coffee table in the lounge, and the hot tub is great in all weather too!<br><br><strong>Nearby options:</strong><br><br><strong>Pirates Cove, Courtown</strong><br>Pirates Cove specifically describes itself as suitable for wet days and offers indoor bowling, arcade games and other indoor entertainment. <a href="https://piratescove.ie/activities/indoor/?utm_source=chatgpt.com" target="_blank" rel="noreferrer">Pirates Cove — Indoor Activities</a>.<br><br><strong>Kid Zone, Gorey</strong><br>Kid Zone is an indoor children\'s play centre in Gorey Business Park, making it a useful option for younger children when the weather isn\'t cooperating.<br><br><strong>Movies at Gorey</strong><br>Movies at Gorey provides another easy rainy-day option, particularly for families or teenagers.<br><br><strong>Wells House &amp; Gardens</strong><br>Wells House &amp; Gardens is another excellent option, particularly when the weather is mixed. The attraction includes the Victorian house, guided tours, gardens, woodland walks, fairy trails, an animal farm and adventure playground. Discover Ireland specifically lists it as a rainy-day attraction. <a href="https://wellshouse.ie/?utm_source=chatgpt.com" target="_blank" rel="noreferrer">Wells House &amp; Gardens — official website</a>.'],
 ['Is Kia Ora Mini Farm suitable if the weather is showery?','Yes, it can still work well on a mixed-weather day. There are indoor and covered areas as well as outdoor activities, so a passing shower doesn\'t necessarily mean abandoning the visit. Current local visitor information describes Kia Ora as a family attraction and specifically highlights it for cloudy days.'],
 ['Where is your nearest shop?','Hughes Londis at Ballymoney crossroads is a one-stop shop with all the items you need to get by. For larger supermarket shops, Aldi, Lidl, Polone, Dunnes and Tesco are a ten-minute drive away in Gorey Town Centre.'],
 ['Are there restaurants near Country Beach Escape?','Yes. Ballymoney has a few restaurants to choose from. We go to Seafield Hotel Bistro a lot; they also offer a more formal dining experience at the hotel. The local pub, The Orphan Girl, has pizza, steak, burgers and fish options — check directly, as food is offered seasonally. The local golf club also has a restaurant offering which we have yet to try: <a href="https://www.facebook.com/theviewrestaurantatcourtowngolfclub/" target="_blank" rel="noreferrer">The View Restaurant at Courtown Golf Club</a>. The Duck at Marlfield House is another spot for a fancy meal, offering lunch, afternoon tea and dinner. Check directly, as it is seasonal and is not open all week; it also has beautiful gardens and woodland to explore. Gorey has a surprisingly good choice of restaurants, cafés, takeaways and pubs, with most options around a 10-minute drive from the house.<br><br><strong>Some popular choices include:</strong><br>Raspberry Restaurant<br>One Hundred Degrees Restaurant and Wine Bar<br>Table Forty One<br>The Kitchen @ Gorey<br><br>For a wider choice, the local <a href="https://lovegorey.ie/eat-drink-directory/?utm_source=chatgpt.com" target="_blank" rel="noreferrer">Love Gorey Eat &amp; Drink Guide</a> lists restaurants, cafés, takeaways and pubs throughout Gorey and North Wexford.'],
 ['How do I book?','Bookings can be made via Airbnb or directly for significantly better rates via WhatsApp at 0868215176. I offer 10% off Airbnb rates and 12% for returning guests.'],
 ['Can I book Country Beach Escape directly, and is it cheaper than Airbnb?','Yes, Booking directly is the best way to guarantee the cheapest rate. I usually offer 10% less than the rate advertised on Airbnb and 12% reduction for returning guests. WhatsApp Julianne on 0868215176 now to check your dates.'],
 ['How close is your nearest beach?','Ballymoney North is a sandy beach six minutes\' drive away and about a 33-minute walk. It is the most popular beach nearby. Kiltennel Beach is another favourite: four minutes by car, with pebbles, sand at times and a forest walk alongside it. Courtown Beach is nine minutes by car, while Cahore South Beach is 24 minutes away via Riverchapel and the coast road (R742).'],
 ['How far is Ballymoney Beach?','Just a few minutes by car.'],
 ['Do you have direct access to the beach?','No. We are on the wrong side of the road and are not directly on the coast, but many beaches are only a few minutes\' drive away. A car is handy for carrying beach gear, and there is plenty of parking at nearby beaches.'],
 ['How many bedrooms are there?','There is one super-king room on the first floor, along with a double room, a bunk-bed room with two single beds, and a full bathroom with a large shower. The second double bedroom is on the ground floor for guests with lower accessibility needs; there is also a shower and toilet room on the ground floor.'],
 ['Is it a comfortable space for a large group?','The property accommodates up to eight guests. There is a very large, spacious lounge and additional seating in the kitchen. The lower bedroom can be set up as a gaming teen hangout zone. The kitchen has a large table with extendable options, and in good weather there are additional dining and seating areas plus sun loungers in the garden and patio area. Comfort is my top priority.'],
 ['Can two families stay together?','Yes. The house comfortably sleeps eight guests.'],
 ['How many cars can be parked at your property?','There is free space for up to four cars, and an electric charging port is available: the first charge is free, with further charging at cost. A report can be provided on request.'],
 ['What are the check-in / out times?','Check-in is usually flexible and check-out is normally by 2pm. When guests are arriving on the same day, check-out is by 11am to allow for a 4pm check-in.'],
 ['Is the hot tub available all year?','Yes, the hot tub is available all year. It is heated to 39°C for adult-only check-ins and set to 37°C for safe use by children. The area is not covered so you can enjoy the stars in the low light pollution, and the hot tub is sanitised before every check-in.'],
 ['Is the hot tub private?','Yes. Guests have exclusive use of the hot tub throughout their stay.'],
 ['How do you accommodate children?','A cot and bed rail are available on request, along with a bath seat, high chair and children\'s dining plates, cutlery, bowls and trays. There is a games and craft cabinet in the kitchen, plus Magnatiles, cards and other games in the lounge. The large garden is great for impromptu football matches and summer hammocks. We are highly rated for families and teenagers, and there are playgrounds nearby in the safe gated environment.'],
 ['I like to cook, how well equipped is your kitchen?','I also love to cook! The kitchen has a double-tray air fryer, Sage combi oven / microwave / steamer, Monsieur Cuisine (a Thermomix equivalent), a proper coffee maker with milk steamer, kettle, electric hob, and all the pots, pans and dishes you need for a five-course meal if necessary. It really is a home from home.'],
 ['I\'m a coffee snob — what coffee machine do you have?','I provide Lavazza ground coffee and Nescafé Gold instant coffee. We have a De’Longhi coffee machine with a milk steamer, plus small and large cafetières. For tea drinkers like myself, there is also a range of teapots with Barry\'s Tea bags available.'],
 ['Are pets allowed?','Yes. Furry friends are important members of the family and deserve a holiday too! I usually request no more than two large dogs.']
];const faqLinks={'How far is Gorey town?':['/to-do/local-area','Explore the local area on our To Do page.'],'How far is Wexford Town?':['/to-do/local-area','Explore the local area on our To Do page.'],'What can we do with children near Gorey?':['/to-do/farms-petting-zoos','Find more family ideas on our To Do page.'],'What is there to do for teenagers?':['/to-do/outdoor-activities','Explore more active ideas on our To Do page.'],'What can we do on a rainy day?':['/to-do/indoor-activities','See more indoor ideas on our To Do page.'],'Is Kia Ora Mini Farm suitable if the weather is showery?':['/to-do/farms-petting-zoos','Explore more family activities on our To Do page.'],'Are there restaurants near Country Beach Escape?':['/to-do/local-pubs-restaurants','See our local food guide on the To Do page.'],'How close is your nearest beach?':['/to-do/walks-trails-greenways','Explore beaches and walks on our To Do page.']};return `<section class="page faq-page"><div class="faq-intro"><p class="eyebrow">PLAN YOUR STAY</p><h1>Frequently asked questions</h1><p>Everything you need to know before your Country Beach Escape. Can't find what you're looking for? <a href="/contact-us">Get in touch</a>.</p></div><div class="faq-list">${faqs.map(([question,answer],index)=>`<details class="faq-item"${index===0?' open':''}><summary><span>${question}</span><span class="faq-icon" aria-hidden="true"></span></summary><p>${answer}${faqLinks[question]?` <a href="${faqLinks[question][0]}">${faqLinks[question][1]}</a>`:''}</p></details>`).join('')}</div></section>`}
function calendar(){return `<section class="page calendar-page"><div class="calendar-intro"><p class="eyebrow">PLAN YOUR STAY</p><h1>Availability calendar</h1><p>The calendar below shows Airbnb availability only. Direct booking has the widest choice of dates and our best available rate.</p></div><section class="calendar-book-direct"><div><h2>Booking directly</h2><p>We'll personally check availability and provide a tailored quotation for your stay.</p></div><ul><li>Save over 10%, 12% for returning guests.</li><li>No Airbnb service fees</li><li>Early check-in when available</li><li>Late check-out when available</li></ul><div>${button('Enquire')}</div></section><div class="calendar-frame"><iframe class="calendar" src="https://www.google.com/calendar/embed?color=%23a47ae2&mode=month&showCalendars=1&showPrint=0&showTz=0&src=oqla229439rkclp3dq77vuartevnao5g@import.calendar.google.com" title="Availability calendar"></iframe></div></section>`}
function galleryPage(){return `<section class="page gallery-page"><div class="gallery-intro"><p class="eyebrow">COUNTRY BEACH ESCAPE</p><h1>Gallery</h1><p>Explore the rooms and spaces that make up your stay.</p></div>${galleryGroups.map(([title,images])=>`<section class="gallery-section"><h2>${title}</h2><div class="gallery">${images.map((src,index)=>`<img loading="lazy" src="${src}" alt="${title} at Country Beach Escape, photo ${index+1}">`).join('')}</div></section>`).join('')}</section>`}
function todo(){return `<section class="todo-landing"><div class="todo-intro"><p class="eyebrow">COUNTRY BEACH ESCAPE</p><h1>Get to know the area a little...</h1><p>Handpicked ideas for days out, eating out, family fun and local essentials.</p></div><div class="todo-grid">${Object.entries(todoSections).map(([slug,[title]])=>`<a href="/to-do/${slug}"><img loading="lazy" src="${todoImages[slug]}" alt="${title}"><span>Explore</span><strong>${title}</strong><b>→</b></a>`).join('')}<a href="https://www.google.com/maps/contrib/105320640410851453895/reviews/@52.6969146,-6.3552974,11z/data=!4m3!8m2!3m1!1e1?entry=ttu" target="_blank" rel="noreferrer"><img loading="lazy" src="/images/todo/reviews.jpg" alt="Our reviews of local spots"><span>Explore</span><strong>Our Reviews of local spots</strong><b>→</b></a></div></section>`}
function todoDetail(slug){const item=todoSections[slug];if(!item)return todo();const guideLinks=Object.entries(todoSections).map(([guideSlug,[title]])=>`<a href="/to-do/${guideSlug}"${guideSlug===slug?' class="current" aria-current="page"':''}><img src="${todoImages[guideSlug]}" alt=""><span>${title}</span></a>`).join('');const detailImage=slug==='local-markets-shopping'?`<figure class="todo-detail-feature"><img src="/images/orphan-girl-market.jpg" alt="The Orphan Girl Samhradh Market, every Wednesday 10am to 1pm"><figcaption>Samhradh Market at The Orphan Girl</figcaption></figure>`:'';const todoWhatsapp=`${whatsapp}?text=${encodeURIComponent(`Hi Julianne, I have a question about ${item[0]}.`)}`;return `<section class="page todo-detail"><aside class="todo-detail-sidebar"><div class="todo-detail-heading"><a class="back" href="/to-do">← All local guides</a><p class="eyebrow">LOCAL GUIDE</p><h1>${item[0]}</h1></div><nav class="todo-side-nav" aria-label="Explore other local guides"><p>Explore more</p>${guideLinks}</nav></aside><div class="todo-detail-content">${item[1].split(/(?<=\.)\s+/).map(p=>`<p>${p}</p>`).join('')}${detailImage}<p>${button('Book Direct')}</p><a class="todo-whatsapp-button" href="${todoWhatsapp}" target="_blank" rel="noreferrer">Ask Julianne on WhatsApp</a></div></section>`}
function welcome(){const guestLinks=[['/to-do/transport','Transport','↗'],['/to-do/take-aways','Take aways','↗'],['/to-do','Things to do','↗'],['https://maps.google.com/?q=52.672587,-6.224395','Location','⌖']];return `<section class="welcome-page"><div class="welcome-intro"><p class="eyebrow">COUNTRY BEACH ESCAPE</p><h1>Welcome Book</h1><p>This guide introduces you to our home and answers the most common questions during your stay. If you cannot find what you need, please <a href="${whatsapp}" target="_blank" rel="noreferrer">WhatsApp Julianne</a>.</p><p>We hope you enjoy the house as much as we do!</p></div><div class="welcome-grid welcome-icon-grid">${welcomeSections.map(([slug,title])=>`<a href="/welcome/${slug}"><img src="/images/welcome/${slug}.png" alt=""><strong>${title}</strong></a>`).join('')}</div><div class="welcome-more"><p class="eyebrow">OUT AND ABOUT</p><div class="welcome-grid welcome-extra-grid">${guestLinks.map(([href,title,icon])=>`<a href="${href}"${href.startsWith('http')?' target="_blank" rel="noreferrer"':''}><span class="welcome-card-icon" aria-hidden="true">${icon}</span><strong>${title}</strong></a>`).join('')}</div></div></section>`}
function welcomeDetail(slug){const section=welcomeSections.find(([itemSlug])=>itemSlug===slug);if(!section)return welcome();const [,,icon,copy]=section;const title=section[1];const guideLinks=welcomeSections.map(([itemSlug,itemTitle,itemIcon])=>`<a href="/welcome/${itemSlug}"${itemSlug===slug?' class="current" aria-current="page"':''}><span aria-hidden="true">${itemIcon}</span>${itemTitle}</a>`).join('');let extra='';if(slug==='instructionvideos')extra=`<div class="welcome-video-grid">${welcomeVideos.map(([videoTitle,id])=>`<article><iframe src="https://www.youtube.com/embed/${id}" title="${videoTitle}" allowfullscreen></iframe><h2>${videoTitle}</h2></article>`).join('')}</div>`;if(slug==='waste')extra=`<p><a href="https://mywaste.ie/dispose-waste/at-home/three-bin-system/" target="_blank" rel="noreferrer">Read the Irish three-bin system guide</a>.</p><div class="welcome-video"><iframe src="https://www.youtube.com/embed/FPzxf56-xSw" title="Waste management instructions" allowfullscreen></iframe></div>`;if(slug==='hot-tub')extra=`<div class="welcome-video"><iframe src="https://www.youtube.com/embed/nwfnoGXxjs8" title="How to open and close the hot tub" allowfullscreen></iframe></div>`;if(slug==='appliances')extra=`<p><a href="/instructionvideos">Watch the useful appliance videos</a>.</p>`;if(slug==='review-feedback')extra=`<p><a href="https://g.page/r/Ca0lEk5jBtIqEAE/review" target="_blank" rel="noreferrer">Leave a Google review</a>.</p>`;if(slug==='comeback')extra=`<p><a class="button" href="${directBookingWhatsapp}" target="_blank" rel="noreferrer">Book your next stay direct</a></p>`;return `<section class="welcome-detail"><aside class="welcome-detail-sidebar"><div class="welcome-detail-heading"><a class="back" href="/welcome">← Welcome Book</a><p class="eyebrow">GUEST GUIDE</p><span class="welcome-detail-icon" aria-hidden="true">${icon}</span><h1>${title}</h1></div><nav class="welcome-side-nav" aria-label="Explore Welcome Book"><p>Welcome Book</p>${guideLinks}</nav></aside><article class="welcome-detail-content">${slug==='instructionvideos'?'':copy.split(/(?<=\.)\s+/).map(p=>`<p>${p}</p>`).join('')}${extra}<p class="welcome-help">Need a hand? <a href="${whatsapp}" target="_blank" rel="noreferrer">Message Julianne on WhatsApp</a>.</p></article></section>`}
function housekeeping(){const staffVideos=[['Housekeeping guide','https://drive.google.com/file/d/13yQzlakr_kezJe5JDIpqoG1AvNekpdl0/preview'],['Smart lock','https://drive.google.com/file/d/1VS7xih2XPxj55ZJMKkAAMDZgpAeTVt6x/preview'],['Washer dryer','https://drive.google.com/file/d/12C7tSaXL7LToCKH84w07tGP_paBAcW7F/preview'],['Waste management','https://drive.google.com/file/d/1ETWTooPet2HA0yTqiKXlGWNsWCpurMQW/preview'],['Open & close hot tub','https://drive.google.com/file/d/1cykqbyqeuL2s-_PZZ1qRbQlIyyzxqRiH/preview'],['Change hot-tub temperature','https://drive.google.com/file/d/1ta7eD1CkDoYsU6coPLPSfsH0YVZOBMHa/preview'],['Hot tub: no-power fix','https://drive.google.com/file/d/17j_nN8wi9trouq-nj7u-X9VQ6FxVYlgb/preview'],['Hot tub: IR error fix','https://drive.google.com/file/d/16lRHvdLTuZQo1Qd7usX5QuWuWGVFZu3F/preview'],['Headboards','https://drive.google.com/file/d/1EpwOqzmJnIu4bMnbJtOQhMrHEDUyHWYs/preview'],['Folding','https://drive.google.com/file/d/1IEVVRrkxqQvKUctIjHWjHq4MFXsEaQ0t/preview']];return `<section class="staff-page"><div class="staff-intro"><p class="eyebrow">COUNTRY BEACH ESCAPE · STAFF</p><h1>Housekeeping Hub</h1><p>You are the main reason for the success of the business. Thank you — your care makes every guest stay special.</p></div><section class="staff-section"><h2>Guides & training videos</h2><div class="staff-video-grid">${staffVideos.map(([title,src])=>`<article><iframe src="${src}" title="${title}" allowfullscreen></iframe><h3>${title}</h3></article>`).join('')}</div></section><section class="staff-section staff-two-column"><div><h2>Hot-tub care</h2><ul><li>Water should always be crystal clear; regular chlorine dosing usually keeps it right.</li><li>Use clarifier if needed. For powder, use one to two teaspoons — the same dose as chlorine.</li><li>Check that the lid is secure and opened correctly; this is the most common source of damage.</li><li>Fake tan can leave an orange waterline and should be scrubbed away.</li><li>If something does not smell right, check the filters. Four spare filters are stored in the shed.</li></ul><iframe class="staff-feature-video" src="https://www.youtube.com/embed/YVdspPqhrQk" title="Hot tub deep clean" allowfullscreen></iframe><p class="staff-caption">Hot-tub deep clean</p></div><div><h2>Property set-up</h2><ul><li>Please leave baby shampoo, monitor, night light, spare bed linen and blankets with the made-up cot.</li><li>Leave toddler shampoo visible in the bathroom and the white-and-green step by the sink.</li><li>Before packing away the cot, wipe it with antibacterial spray. Store the cot in the large white plastic bag and its mattress in the other bag.</li><li>Make sure all outside cushions are in the storage box.</li><li>Leave sunloungers elevated as shown, to help keep the grass healthy.</li><li>Remove cobwebs, check furniture for bird droppings and clean them with the supplied outdoor spray.</li><li>Put rain covers on both egg chairs and check cushions underneath for dirt.</li></ul></div></section><section class="staff-section"><h2>Guest messages</h2><div class="staff-message-grid"><details open><summary>Week-of-arrival message</summary><p>Welcome guests to Ballymoney, share their arrival and departure details, gate and door access, hot-tub details, Wi-Fi information, address, useful videos and the house rules. Ask guests to share the message with their group and to WhatsApp with any questions during business hours.</p></details><details><summary>Afternoon-before-departure message</summary><p>Thank guests for their stay, remind them about the 2pm check-out, dishwasher, waste, garden, hot-tub lid, beds, towels, furniture, covers, windows, keys and damage reporting. Invite them to book direct next time and leave a Google review.</p></details><details><summary>Reusable links</summary><p><a href="/welcome">Welcome Book</a> · <a href="/instructionvideos">Useful videos</a> · <a href="/to-do">Local To Do guide</a></p></details></div></section></section>`}
function contact(){return `<section class="page contact"><section class="whatsapp-priority"><div><p class="eyebrow">THE QUICKEST WAY TO REACH US</p><h1>Message Julianne on WhatsApp</h1><p>For a quick answer about dates, rates or your stay, send a message and Julianne will be happy to help.</p></div><a href="${whatsapp}" class="whatsapp-priority-button" target="_blank" rel="noreferrer">How can I help?</a></section><section class="contact-location"><h2>Location</h2><iframe class="map" src="https://maps-api-ssl.google.com/maps?hl=en-US&ll=52.672587,-6.224395&output=embed&q=The+Meadows,+Prospect,+Co.+Wexford,+Ireland+(The+Meadows)&z=14" title="Map"></iframe></section><section class="contact-actions" aria-label="Contact and booking options"><article class="contact-action contact-action-message"><span class="contact-action-icon" aria-hidden="true">◔</span><h2>Contact us</h2><p>Phone during business hours GMT please.</p><p><a href="mailto:countrybeachescape@gmail.com">countrybeachescape@gmail.com</a><br><a href="tel:+353868215176">0868215176</a></p><a href="${whatsapp}" class="contact-action-button whatsapp-button" target="_blank" rel="noreferrer" aria-label="Message Julianne on WhatsApp">How can I help?</a></article><article class="contact-action contact-action-review"><h2>Leave a review</h2><p>Had a wonderful stay? We would love to hear from you.</p><a class="google-review-badge" href="https://g.page/r/Ca0lEk5jBtIqEAE/review" target="_blank" rel="noreferrer" aria-label="Leave a Google review for Country Beach Escape"><img src="/images/google-review-us.png" alt="Review us on Google"></a></article><article class="contact-action contact-action-book"><span class="contact-action-icon" aria-hidden="true">✦</span><h2>Book direct</h2><p>Get the best available price and a personal welcome from Julianne.</p><p>Credit cards accepted.</p><a href="${directBookingWhatsapp}" class="button" target="_blank" rel="noreferrer">Check availability</a></article></section><section class="direct-booking" id="direct-booking"><div><p class="eyebrow">BOOK DIRECT</p><h2>Book your stay in three simple steps</h2><p>Booking directly means you receive a personal quote and the best available rate for your dates.</p></div><ol class="booking-steps"><li><span>1</span><div><h3>Send your dates</h3><p>Message Julianne on WhatsApp with your preferred dates and number of guests.</p></div></li><li><span>2</span><div><h3>Receive your quote</h3><p>Julianne will confirm availability and your direct-booking price.</p></div></li><li><span>3</span><div><h3>Pay securely</h3><p>You will receive a secure Revolut Business payment link for the agreed amount.</p></div></li></ol><a href="${directBookingWhatsapp}" class="direct-booking-button" target="_blank" rel="noreferrer">Check availability on WhatsApp</a><p class="direct-booking-note">You will never be asked to enter payment details on this website.</p></section>${enquiryForm()}</section>`}

function enquiryForm(){return `<section class="contact-form-section" id="contact-form"><div class="contact-form-intro"><p class="eyebrow">ENQUIRY FORM</p><h2>Contact &amp; Enquiry</h2><p>The availability shown on our Calendar reflects our Airbnb allocation only. Fill in the form below, call or WhatsApp Julianne on <a href="tel:+353868215176">0868215176</a>.</p><p>For the widest choice of dates and our best available rates, we recommend contacting us directly. We'll personally check availability and provide a tailored quotation for your stay.</p></div><div class="booking-direct-benefits"><h3>Booking directly</h3><ul><li>Save over 10%, 12% for returning guests.</li><li>No Airbnb service fees.</li><li>Early check in when available.</li><li>Late check out when available.</li></ul><p>We look forward to welcoming you to Country Beach Escape.</p></div><details class="booking-terms"><summary>Rates, terms &amp; booking information</summary><p>My nightly rates when paid directly are usually between €220 and €450. My cleaning fee is an additional €150. Rates depend on periods of demand. Its worth enquiring.</p><ul><li>Minimum 2 - 7 nights required, depends on season.</li><li>Max 8 people per booking.</li><li>Max 2 pets.</li><li>Payment online available using major payment providers.</li><li>Crypto currency and cash paid on arrival also accepted.</li><li>Deposit of €250 per week to secure booking, balance due 2 weeks before arrival.</li><li>Same cancellation policy as Airbnb Moderate Policy (Full refund 5 days or more before check-in).</li><li>PDF Confirmation invoice / receipt sent by email.</li><li>Once booked, Information messages communicated through WhatsApp.</li></ul><p>Good &amp; Reasonable Deals made for remote workers, Midweek needs, Couple only using one room, construction workers, long term bookings and more.</p></details><form class="booking-contact-form" action="https://formsubmit.co/countrybeachescape@gmail.com" method="POST"><input type="hidden" name="_subject" value="New Country Beach Escape enquiry"><input type="hidden" name="_template" value="table"><input type="hidden" name="_captcha" value="false"><input type="hidden" name="_next" value="https://country-beach-escape.pages.dev/contact-us?sent=1#contact-form"><input type="hidden" name="Source" value="Country Beach Escape website"><input type="text" name="_honey" class="honeypot" tabindex="-1" autocomplete="off"><div class="form-grid"><label>Name <span aria-hidden="true">*</span><input type="text" name="Name" autocomplete="name" required></label><label>Email <span aria-hidden="true">*</span><input type="email" name="Email" autocomplete="email" required></label><label>Phone number<input type="tel" name="Phone number" autocomplete="tel"></label><label>Number of people (max capacity 8) <span aria-hidden="true">*</span><input type="number" name="Number of people" min="1" max="8" required></label><label>Check in date <span aria-hidden="true">*</span><input type="date" name="Check in date" required></label><label>Check out date <span aria-hidden="true">*</span><input type="date" name="Check out date" required></label></div><fieldset><legend>Number of rooms</legend><div class="checkbox-grid"><label><input type="checkbox" name="Rooms" value="Super King Room - First Floor"> Super King Room - First Floor</label><label><input type="checkbox" name="Rooms" value="Double Room - Ground Floor"> Double Room - Ground Floor</label><label><input type="checkbox" name="Rooms" value="Double Room - First Floor"> Double Room - First Floor</label><label><input type="checkbox" name="Rooms" value="Bunk Bed Room - First Floor"> Bunk Bed Room - First Floor</label></div></fieldset><fieldset><legend>Any pets? <span aria-hidden="true">*</span></legend><div class="radio-options"><label><input type="radio" name="Any pets?" value="Yes" required> Yes</label><label><input type="radio" name="Any pets?" value="No" required> No</label></div></fieldset><label class="form-comments">Comments <span class="field-hint">Baby items needed, special occasion, number &amp; type of pet, repeat booker, couple-only deal or another query.</span><textarea name="Comments" rows="6"></textarea></label><button class="form-submit" type="submit">Send enquiry</button></form></section>`}
function owner(){return `<section class="page owner-page"><div class="owner-intro"><p class="eyebrow">YOUR HOST</p><h1>Meet the owner</h1><div class="owner-profile-frame"><img class="owner-profile" src="/images/julianne-profile.png" alt="Julianne Hickey"></div><h2>Julianne Hickey</h2></div><div class="owner-content"><p>Qualified in BSc Hospitality Management in 2002 and holds a post graduate IT Teachers Diploma. Organised with excellent interpersonal skills, highly regarded by colleagues, students and employers. I have been working in the hospitality industry since 1995. Began in our 13 bedroom family guesthouse in Ranelagh in 1995 and from 2017–2020 managed a short let apartment in Dublin with a Booking.com review score of 9.6/10 after over 100 reviews. Happy to share our new family holiday home with others from around the world so they too can enjoy its fantastic energy, comfort and light filled rooms.</p><p>I am a proud part time teacher for Liberties College in the heart of the City of Dublin. It is part of a large network of Further Education &amp; Training institutions CityofDublinETB.ie. I teach a wide variety of subjects from Tourism, Airline and Hospitality subjects to Management and IT subjects. Teaching is what I love along with sharing the parenting of 2 children with my husband.</p><blockquote>“Hospitality is the space of possibility that opens up between guest and host when both parties willingly engage in this precarious mutual trust.”<cite>How to Soften Corners, Jennie Moran<br><em>Visser, 1991, p.91</em></cite></blockquote><p>Looking forward to hosting you!</p></div></section>`}
const paths={'/':home,'/the-house':home,'/faq':faq,'/calendar':calendar,'/gallery':galleryPage,'/to-do':todo,'/contact-us':contact,'/owner':owner,'/welcome':welcome,'/instructionvideos':()=>welcomeDetail('instructionvideos'),'/housekeeping':housekeeping};
const todoMatch=location.pathname.match(/^\/to-do\/([^/]+)$/);
const welcomeMatch=location.pathname.match(/^\/welcome\/([^/]+)$/);
document.querySelector('#app').innerHTML=shell(todoMatch?todoDetail(todoMatch[1]):(welcomeMatch?welcomeDetail(welcomeMatch[1]):(paths[location.pathname]||home)()));
document.querySelector('.menu').addEventListener('click',()=>document.querySelector('nav').classList.toggle('open'));
